  backupCourse(courseId: number, destDir: string, options?: { withUsers?: boolean | undefined; anonymize?: boolean | undefined; timeoutMs?: number | undefined; }): Promise<{ changed: string; file: import("./core/files.js").DownloadedFile; }>;
